'use strict';
const menu = document.querySelector('.menu-toggle');
const nav = document.getElementById('main-nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu();});
function showDialog(dialog){dialog.showModal();document.body.classList.add('no-scroll');}
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('no-scroll'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
const bookingDialog=document.getElementById('booking-dialog');
document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>showDialog(bookingDialog)));
const arrival=document.getElementById('arrival'),departure=document.getElementById('departure');
const localDate = date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const nextDay=value=>{const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return localDate(d);};
const today=localDate(new Date());arrival.min=today;arrival.value=today;departure.min=nextDay(today);departure.value=departure.min;
function validateStay(){arrival.setCustomValidity(arrival.value<today?'Choose today or a future arrival date.':'');departure.setCustomValidity(departure.value<=arrival.value?'Departure must be after arrival.':'');return arrival.checkValidity()&&departure.checkValidity();}
arrival.addEventListener('input',()=>{departure.min=nextDay(arrival.value||today);if(departure.value<=arrival.value)departure.value=departure.min;validateStay();document.getElementById('stay-summary').hidden=true;});
departure.addEventListener('input',()=>{validateStay();document.getElementById('stay-summary').hidden=true;});
document.getElementById('guests').addEventListener('change',()=>{document.getElementById('stay-summary').hidden=true;});
document.getElementById('stay-form').addEventListener('submit',e=>{e.preventDefault();if(!validateStay()){e.target.reportValidity();return;}const count=(Date.parse(departure.value)-Date.parse(arrival.value))/86400000;const format=v=>new Date(v+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});document.getElementById('stay-summary-text').textContent=`${format(arrival.value)} – ${format(departure.value)} · ${count} night${count===1?'':'s'} · ${document.getElementById('guests').value}`;const result=document.getElementById('stay-summary');result.hidden=false;result.querySelector('a').focus();});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-room]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.room!==button.dataset.filter&&!(button.dataset.filter==='queen'&&card.dataset.room==='double');});}));
const roomDetails={king:['King rooms','King options include classic and corner rooms. The inn’s published room descriptions list a king bed, sitting area, desk, and television. Ask about the individual room you are considering.'],queen:['Queen rooms','Classic queen rooms offer a queen bed. Some layouts also include a sleeper sofa. Confirm the bed configuration and amenities of your selected room.'],double:['Double queen rooms','The inn lists double rooms with two queen beds, a desk area, and television. Ask the front desk which room best fits your group.'],suite:['Classic suites','Classic suites are described with a queen bed and a separate living area. Ask about sofa or sleeper-sofa arrangements and the amenities in the specific suite.']};
document.querySelectorAll('[data-room-detail]').forEach(button=>button.addEventListener('click',()=>{const [title,copy]=roomDetails[button.dataset.roomDetail];document.getElementById('room-dialog-title').textContent=title;document.getElementById('room-dialog-copy').textContent=copy;showDialog(document.getElementById('room-dialog'));}));
const seasons={spring:['SPRING / NEW ARRIVALS','Listen for the season.','Look for returning waterbirds and songbirds. Start at a visitor center and let current conditions shape your route.'],summer:['SUMMER / TAKE THE LONG WAY','Leave time to wander.','Plan a morning walk or a photography outing. Bring water, sun protection, and curiosity, and check the refuge guide before choosing a trail.'],fall:['FALL / MIGRATION SEASON','Look up. Take your time.','Watch for migrating geese, ducks, and sandhill cranes. Bring layers and check trail access before heading out.'],winter:['WINTER / A QUIETER LANDSCAPE','Find beauty in the stillness.','Consider a winter walk or snowshoe outing when conditions allow. Check road access and facilities, and dress for the weather.']};
document.querySelectorAll('[data-season]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-season]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});const [label,title,copy]=seasons[button.dataset.season];document.getElementById('season-label').textContent=label;document.getElementById('season-title').textContent=title;document.getElementById('season-copy').textContent=copy;}));
const contactForm=document.getElementById('contact-form');
if(contactForm){contactForm.addEventListener('submit',e=>{e.preventDefault();if(!contactForm.reportValidity())return;const data=new FormData(contactForm);const name=String(data.get('name')).trim(),email=String(data.get('email')).trim(),message=String(data.get('message')).trim();if(!name||!message)return;const topic=String(data.get('topic'));const draft=`Hello Audubon Inn team,\n\n${message}\n\nThank you,\n${name}\n${email}`;document.getElementById('draft-text').value=draft;document.getElementById('draft-open').href=`mailto:hotelonthemarsh@gmail.com?subject=${encodeURIComponent(topic+' — '+name)}&body=${encodeURIComponent(draft)}`;document.getElementById('draft-result').hidden=false;document.getElementById('draft-open').focus();});document.getElementById('copy-draft').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('draft-text').value);document.getElementById('copy-status').textContent='Message copied. Paste it into your email app.';}catch{document.getElementById('draft-text').focus();document.getElementById('draft-text').select();document.getElementById('copy-status').textContent='Select and copy the message above.';}});}
